import {Brand} from "@/components/Brand";
export default function NewCourse(){return <main className="section"><div className="container" style={{maxWidth:760}}><div className="section-head"><div><span className="eyebrow">ADMIN</span><h1>Create course</h1><p className="muted">Create the course first; subjects, chapters and lessons can be added next.</p></div><a className="btn btn-secondary" href="/admin/courses">← Courses</a></div><div className="panel"><form className="form" action="/api/courses" method="post"><label>Course title<input name="title" placeholder="JEE Physics Complete Course" required/></label><label>Slug<input name="slug" placeholder="jee-physics-complete-course" required/></label><label>Description<textarea name="description" rows={5}/></label><label>Price (INR)<input name="price" type="number" min="0" step="1" defaultValue="499"/></label><label>Publish<select name="isPublished" defaultValue="true"><option value="true">Published</option><option value="false">Draft</option></select></label><button className="btn btn-primary">Create Course</button></form></div></div></main>}
